sizes in HMC will give results that are # exactly identical to explicitly using a diagonal mass matrix. with tf.compat.v1.name_scope (name,'hmc_leapfrog_integrator_one_step',[ independent_chain_ndims,step_sizes,current_momentum_parts,current_state_parts,current_target_log_prob,current_target_log_prob_grad_parts ]):# Step 1: Update momentum. proposed_momentum_parts = [ v + 0.5 * tf.cast (eps,v.dtype) * g for v,eps,g in zip (current_momentum_parts,step_sizes,current_target_log_prob_grad_parts) ] # Step 2: Update state. proposed_state_parts = [ x + tf.cast (eps,v.dtype) * v for x,eps,v in zip (current_state_parts,step_sizes,proposed_momentum_parts) ] if state_gradients_are_stopped:proposed_state_parts = [ tf.stop_gradient (x) for x in proposed_state_parts ] # Step 3a: Re-evaluate target-log-prob (and grad) at proposed state. [ proposed_target_log_prob,proposed_target_log_prob_grad_parts,] = mcmc_util.maybe_call_fn_and_grads (target_log_prob_fn,proposed_state_parts) if not proposed_target_log_prob.dtype.is_floating:raise TypeError ('`target_log_prob_fn` must produce a `Tensor` ' 'with `float` `dtype`.') if any (g is None for g in proposed_target_log_prob_grad_parts):raise ValueError ('Encountered `None` gradient. Does your target `target_log_prob_fn` ' 'access all `tf.Variable`s via `tf.get_variable`?
' '  current_state_parts: {}
