def _detect_global_scope(node, frame, defframe):
    def_scope = scope = None
    if frame and frame.parent:
        scope = frame.parent.scope()
    if defframe and defframe.parent:
        def_scope = defframe.parent.scope()
    if isinstance(frame, astroid.FunctionDef):
        # If the parent of the current node is a function, then it can be under its scope (defined in, which doesn't concern us) or the `->` part of annotations. The same goes for annotations of function arguments, they'll have the parent the Arguments node.
        if not isinstance(node.parent,(astroid.FunctionDef,astroid.Arguments)):
            return False
        elif any(not isinstance(f,(astroid.ClassDef,astroid.Module)) for f in (frame,defframe)):
            # Not interested in other frames, since they are already not in a global scope.
            return False
        break_scopes = []
        for s in (scope,def_scope):
            # Look for parent scopes. If there is anything different than a module or a class scope, then they frames don't share a global scope.
            parent_scope = s
            while parent_scope:
                if not isinstance(parent_scope,(astroid.ClassDef,astroid.Module)):
                    break_scopes.append(parent_scope)
                    break
                if parent_scope.parent:
                    parent_scope = parent_scope.parent.scope()
                else:
                    break
        if break_scopes and len(set(break_scopes)) != 1:
            # Store different scopes than expected.
            # If the stored scopes are, in fact, the very same, then it means that the two frames (frame and defframe) shares the same scope, and we could apply our lineno analysis over them.
            # For instance, this works when they are inside a function, the node that uses a definition and the definition itself.
            return False
        # At this point, we are certain that frame and defframe shares a scope and the definition of the first depends on the second.
        return frame.lineno < defframe.lineno

